//! The test benches of the VUnit VHDL libraries (`vunit/vhdl/*/test`), with each `run.py`
//! translated into a [`ProjectSpec`].
//!
//! Left out, because the frontend doesn't support what they need (see `UPSTREAM.md`):
//!
//! - `check/test/tb_check_relation*.vhd`: the check preprocessor;
//! - `check/test/tb_check_equal.vhd` and `tb_check_match.vhd`: generated by Python tools in
//!   `run.py`, not checked in;
//! - `com/test/tb_com_codec.vhd`: com codec generation;
//! - `logging/test/tb_location.vhd`: the location preprocessor;
//! - the `Test random` configurations of `tb_sim_time_formatting`, which `run.py` draws with
//!   Python's random generator; one fixed configuration replaces them.
//!
//! AI NOTICE: Generated, minimally reviewed.

use risim_vunit_frontend::Runtime;
use risim_vunit_frontend::SimulatorKind;
use risim_vunit_frontend::pattern::Pattern;
use risim_vunit_frontend::spec::ConfigurationSpec;
use risim_vunit_frontend::spec::Feature;
use risim_vunit_frontend::spec::ProjectSpec;
use risim_vunit_frontend::spec::TestConfigSpec;

use crate::harness;
use crate::harness::RisimDeviations;
use crate::harness::Root;
use crate::harness::config;
use crate::harness::generics;
use crate::harness::target;

/// Runs all testcases of `spec`; the testcases in `failing` must fail and all others pass,
/// changed by `risim` on the `risim` backend.
async fn check(
    simulator: SimulatorKind,
    runtime: &Runtime,
    root: &Root,
    spec: &ProjectSpec,
    failing: &[&str],
    risim: RisimDeviations,
) {
    let outcome = harness::simulate_all(runtime, &root.path, spec, simulator).await;
    outcome.assert_all_pass_except(failing, risim);
}

/// The test files of library `name` (`vunit/vhdl/<name>/test`).
fn test_files(name: &str, skip: impl Fn(&str) -> bool) -> Vec<String> {
    harness::vhd_files(&harness::vhdl_dir().join(name).join("test"), skip)
}

/// A configuration with generics.
fn config_with(name: &str, pairs: &[(&str, &str)]) -> ConfigurationSpec {
    ConfigurationSpec {
        generics: generics(pairs),
        ..config(name)
    }
}

/// Configurations of `target`.
fn configs_of(target_name: &str, configurations: Vec<ConfigurationSpec>) -> TestConfigSpec {
    TestConfigSpec {
        configurations,
        ..target(target_name)
    }
}

pub async fn check_lib(simulator: SimulatorKind) {
    let runtime = harness::runtime().await;
    let root = Root::new();
    let mut spec = ProjectSpec::new();
    let logging_support = harness::vhdl_dir().join("logging/test/test_support_pkg.vhd");
    // Old copies of the generated testbenches may still be around; they're gitignored.
    spec.add_library(
        "lib",
        test_files("check", |name| {
            name.starts_with("tb_check_relation")
                || name == "tb_check_equal.vhd"
                || name == "tb_check_match.vhd"
        }),
    )
    .add_library("logging_tb_lib", [logging_support.to_string()]);
    spec.test_configs.push(configs_of(
        "lib.tb_check",
        vec![
            config_with("using check", &[("use_check_not_check_true", "True")]),
            config_with("using check_true", &[("use_check_not_check_true", "False")]),
        ],
    ));
    // risim: association, enclosing unit, access.
    check(
        simulator,
        &runtime,
        &root,
        &spec,
        CHECK_FAILURES,
        RisimDeviations::AllFailing,
    )
    .await;
}

/// Tests of `run_all_in_same_sim` testbenches that rely on the earlier tests of the same
/// simulation. They pass when all tests of the testbench run in one simulation.
const CHECK_FAILURES: &[&str] = &[
    "lib.tb_check_false.Test should pass on false and logic 0 inputs to sequential checks",
    "lib.tb_check_next.Test should fail when expr is false num_cks enabled cycles after \
     start_event",
    "lib.tb_check_next.Test should handle a mix of passing and failing overlapping checks when \
     allowed",
];

