pub async fn logging(simulator: SimulatorKind) {
    let runtime = harness::runtime().await;
    let root = Root::new();
    let mut spec = ProjectSpec::new();
    spec.add_library(
        "vunit_lib",
        test_files("logging", |name| name == "tb_location.vhd"),
    );
    let tb = "vunit_lib.tb_sim_time_formatting";
    spec.test_configs.push(TestConfigSpec {
        generics: generics(&[("n_performance_iterations", "1")]),
        ..target(tb)
    });
    let mut tests: Vec<(&str, Vec<ConfigurationSpec>)> = Vec::new();
    for (test, cfg_name, test_time, scaling, n_decimals) in sim_time_vectors() {
        let (auto_scaling, expected) = expected_time(test_time, scaling, n_decimals);
        let configuration = config_with(
            &cfg_name,
            &[
                ("test_time", &test_time.to_string()),
                ("scaling", &scaling.to_string()),
                ("n_decimals", &n_decimals.to_string()),
                ("expected", &expected),
                ("auto_scaling", &auto_scaling.to_string()),
            ],
        );
        match tests.iter_mut().find(|(name, _)| *name == test) {
            Some((_, configurations)) => configurations.push(configuration),
            None => tests.push((test, vec![configuration])),
        }
    }
    for (test, configurations) in tests {
        spec.test_configs
            .push(configs_of(&format!("{tb}.{test}"), configurations));
    }
    // risim: image, access.
    check(
        simulator,
        &runtime,
        &root,
        &spec,
        &[],
        RisimDeviations::AllFailing,
    )
    .await;
}

const NATIVE_UNIT_SCALING: i64 = 0;
const AUTO_UNIT_SCALING: i64 = -1;
const FULL_RESOLUTION: i64 = -1;

/// The test vectors of `logging/run.py`: test, configuration, time, scaling and decimals.
#[expect(clippy::too_many_lines, reason = "follows run.py")]
fn sim_time_vectors() -> Vec<(&'static str, String, u64, i64, i64)> {
    let mut vectors = Vec::new();
    let mut add = |test: &'static str, name: String, time: u64, scaling: i64, decimals: i64| {
        vectors.push((test, name, time, scaling, decimals));
    };

    add(
        "Test native unit",
        "no_decimals".to_owned(),
        123_456,
        NATIVE_UNIT_SCALING,
        0,
    );
    for scaling in [1, 1000, 1_000_000, 1_000_000_000] {
        add(
            "Test units of differents scales wrt the resolution_limit",
            format!("scaling={scaling}"),
            123_456,
            scaling,
            0,
        );
    }
    let auto = "Test auto unit";
    add(
        auto,
        "three_integer_digits".to_owned(),
        456_789,
        AUTO_UNIT_SCALING,
        0,
    );
    add(
        auto,
        "two_integer_digits".to_owned(),
        56_789,
        AUTO_UNIT_SCALING,
        0,
    );
    add(
        auto,
        "one_integer_digit".to_owned(),
        6_789,
        AUTO_UNIT_SCALING,
        0,
    );
    let limiting = "Test limiting number of decimals";
    for n_decimals in 0..3 {
        for scaling in [1, 1000, 1_000_000] {
            add(
                limiting,
                format!("n_decimals={n_decimals}_scaling={scaling}"),
                456_789,
                scaling,
                n_decimals,
            );
        }
        add(
            limiting,
            format!("n_decimals={n_decimals}_native_unit"),
            456_789,
            NATIVE_UNIT_SCALING,
            n_decimals,
        );
        add(
            limiting,
            format!("n_decimals={n_decimals}_auto_unit"),
            456_789,
            AUTO_UNIT_SCALING,
            n_decimals,
        );
    }
    add(
        limiting,
        "no significant digits among decimals".to_owned(),
        456_789,
        1_000_000_000,
        3,
    );
    add(
        limiting,
        "some significant digits among decimals".to_owned(),
        456_789,
        1_000_000_000,
        4,
    );
    let full = "Test full resolution";
    for scaling in [1, 1000, 1_000_000, 1_000_000_000] {
        add(
            full,
            format!("scaling={scaling}"),
            123_456,
            scaling,
            FULL_RESOLUTION,
        );
    }
    add(
        full,
        "native_unit".to_owned(),
        123_456,
        NATIVE_UNIT_SCALING,
        FULL_RESOLUTION,
    );
    add(
        full,
        "auto_unit".to_owned(),
        123_456,
        AUTO_UNIT_SCALING,
        FULL_RESOLUTION,
    );
    // `round(123456, -n)` for n = 1..6.
    for (n_zeros, time) in [
        (1, 123_460),
        (2, 123_500),
        (3, 123_000),
        (4, 120_000),
        (5, 100_000),
        (6, 0),
    ] {
        add(
            "Test trailing zeros",
            format!("n_zeros={n_zeros}"),
            time,
            1000,
            3,
        );
    }
    let zero = "Test zero";
    add(
        zero,
        "auto_with_all_decimals".to_owned(),
        0,
        AUTO_UNIT_SCALING,
        FULL_RESOLUTION,
    );
    add(zero, "scaling_with_fix_decimals".to_owned(), 0, 1000, 2);
    add(zero, "scaling_with_no_decimals".to_owned(), 0, 1000, 0);
    // Instead of the configurations that `run.py` draws at random.
    // 2**31 - 1
    let time = 0x7FFF_FFFF;
    add(
        "Test random",
        format!("{time}_{AUTO_UNIT_SCALING}_5"),
        time,
        AUTO_UNIT_SCALING,
        5,
    );
    vectors
}

/// `calculate_generics` of `logging/run.py`: the auto scaling and the expected text.
fn expected_time(test_time: u64, scaling: i64, n_decimals: i64) -> (i64, String) {
    // The number of decimal digits minus one, `floor(log10(value))`.
    let log10 = |value: u64| value.ilog10();
    let auto_scaling = if test_time == 0 || scaling != AUTO_UNIT_SCALING {
        1
    } else {
        10_i64.pow(log10(test_time) / 3 * 3)
    };
    let resolved_scaling = match scaling {
        1.. => scaling,
        NATIVE_UNIT_SCALING => 1,
        _ => auto_scaling,
    };

    let mut digits = test_time.to_string();
    let n_to_use = log10(u64::try_from(resolved_scaling).expect("positive")) as usize;
    if n_to_use >= digits.len() {
        digits = format!("{}{digits}", "0".repeat(n_to_use - digits.len() + 1));
    }
    let split = digits.len() - n_to_use;
    let (integer, fraction) = digits.split_at(split);
    let expected = if n_to_use == 0 {
        match usize::try_from(n_decimals) {
            Ok(decimals @ 1..) => format!("{integer}.{}", "0".repeat(decimals)),
            _ => integer.to_owned(),
        }
    } else {
        match usize::try_from(n_decimals) {
            Ok(0) => integer.to_owned(),
            Err(_) => format!("{integer}.{fraction}"),
            Ok(decimals) if decimals <= n_to_use => {
                format!(
                    "{integer}.{}",
                    fraction.get(..decimals).expect("ASCII digits")
                )
            },
            Ok(decimals) => format!("{integer}.{fraction}{}", "0".repeat(decimals - n_to_use)),
        }
    };
    (auto_scaling, expected)
}

