#[expect(clippy::too_many_lines, reason = "follows run.py")]
pub async fn verification_components(simulator: SimulatorKind) {
    let runtime = harness::runtime().await;
    let root = Root::new();
    let mut spec = ProjectSpec::new();
    spec.add_feature(Feature::Random)
        .add_feature(Feature::VerificationComponents)
        .add_library(
            "vunit_lib",
            test_files("verification_components", |_| false),
        );
    let names = harness::testcase_names(&runtime, &root.path, &spec).await;
    let tests = |tb: &str| harness::tests_of(&names, &format!("vunit_lib.{tb}"));
    let configs = &mut spec.test_configs;
    let mut add = |tb: &str, test: &str, configurations: Vec<ConfigurationSpec>| {
        configs.push(configs_of(
            &format!("vunit_lib.{tb}.{test}"),
            configurations,
        ));
    };

    for test in tests("tb_avalon_slave") {
        let configurations = tb_cfg_configs(
            &[
                ("data_width", &["32"]),
                ("num_cycles", &["1", "2", "64"]),
                ("readdatavalid_prob", &["1.0", "0.3"]),
                ("waitrequest_prob", &["0.0", "0.4"]),
            ],
            &[
                "data_width",
                "readdatavalid_prob",
                "waitrequest_prob",
                "num_cycles",
            ],
        );
        add("tb_avalon_slave", test, configurations);
    }

    for test in tests("tb_avalon_master") {
        let order = [
            "readdatavalid_prob",
            "waitrequest_prob",
            "write_prob",
            "read_prob",
            "transfers",
        ];
        let configurations = if test == "wr single rd single" {
            tb_cfg_configs(
                &[
                    ("transfers", &["1"]),
                    ("readdatavalid_prob", &["1.0"]),
                    ("waitrequest_prob", &["0.0"]),
                    ("write_prob", &["1.0"]),
                    ("read_prob", &["1.0"]),
                ],
                &order,
            )
        } else {
            tb_cfg_configs(
                &[
                    ("transfers", &["64"]),
                    ("readdatavalid_prob", &["1.0", "0.3"]),
                    ("waitrequest_prob", &["0.0", "0.7"]),
                    ("write_prob", &["1.0", "0.3"]),
                    ("read_prob", &["1.0", "0.3"]),
                ],
                &order,
            )
        };
        add("tb_avalon_master", test, configurations);
    }

    for test in tests("tb_wishbone_slave") {
        let configurations = wishbone_configs(
            &["8", "32"],
            &["1", "64"],
            &["1.0"],
            &["0.3", "1.0"],
            &["0.4", "0.0"],
            &["True"],
        );
        add("tb_wishbone_slave", test, configurations);
    }

    for test in tests("tb_wishbone_master") {
        let configurations = if test == "slave comb ack" {
            wishbone_configs(&["32"], &["64"], &["1.0"], &["1.0"], &["0.0"], &["False"])
        } else {
            wishbone_configs(
                &["8", "32"],
                &["1", "64"],
                &["0.3", "1.0"],
                &["0.3", "1.0"],
                &["0.4", "0.0"],
                &["True"],
            )
        };
        add("tb_wishbone_master", test, configurations);
    }

    let check_pattern = Pattern::new("*check");
    for test in tests("tb_axi_stream") {
        if !check_pattern.matches(test) {
            continue;
        }
        let mut configurations = Vec::new();
        for id in ["0", "8"] {
            for dest in ["0", "8"] {
                for user in ["0", "8"] {
                    for data in ["8", "16"] {
                        configurations.push(config_with(
                            &format!("id_l={id} dest_l={dest} user_l={user} data_l={data}"),
                            &[
                                ("g_data_length", data),
                                ("g_id_length", id),
                                ("g_dest_length", dest),
                                ("g_user_length", user),
                            ],
                        ));
                    }
                }
            }
        }
        add("tb_axi_stream", test, configurations);
    }
    let no_tkeep = TestConfigSpec {
        generics: generics(&[("g_data_length", "16")]),
        ..target("vunit_lib.tb_axi_stream.test passing with no tkeep")
    };

    let checker = "tb_axi_stream_protocol_checker";
    let tdata = Pattern::new("*passing*tdata*");
    let tid_width = Pattern::new("*failing*tid width*");
    for test in tests(checker) {
        if tdata.matches(test) {
            let configurations = ["0", "8", "32"]
                .into_iter()
                .map(|length| {
                    config_with(&format!("data_length={length}"), &[("data_length", length)])
                })
                .collect();
            add(checker, test, configurations);
        } else if tid_width.matches(test) {
            add(
                checker,
                test,
                vec![
                    config_with("dest_length=25", &[("dest_length", "25")]),
                    config_with(
                        "id_length=8 dest_length=17",
                        &[("id_length", "8"), ("dest_length", "17")],
                    ),
                ],
            );
        }
    }
    add(
        checker,
        "Test failing check of that tready comes within max_waits after valid",
        ["0", "8"]
            .into_iter()
            .map(|waits| config_with(&format!("max_waits={waits}"), &[("max_waits", waits)]))
            .collect(),
    );
    configs.push(no_tkeep);

    // risim: enclosing unit, image, access, driver.
    check(
        simulator,
        &runtime,
        &root,
        &spec,
        &[],
        RisimDeviations::AllFailing,
    )
    .await;
}

/// `gen_wb_tests` of `verification_components/run.py`.
fn wishbone_configs(
    dat_width: &[&str],
    num_cycles: &[&str],
    strobe_prob: &[&str],
    ack_prob: &[&str],
    stall_prob: &[&str],
    slave_inst: &[&str],
) -> Vec<ConfigurationSpec> {
    tb_cfg_configs(
        &[
            ("dat_width", dat_width),
            ("num_cycles", num_cycles),
            ("strobe_prob", strobe_prob),
            ("ack_prob", ack_prob),
            ("stall_prob", stall_prob),
            ("slave_inst", slave_inst),
            ("adr_width", &["32"]),
        ],
        &[
            "dat_width",
            "adr_width",
            "strobe_prob",
            "ack_prob",
            "stall_prob",
            "num_cycles",
            "slave_inst",
        ],
    )
}

/// One configuration per combination of `values` (in `itertools.product` order), named after
/// and with the generic `encoded_tb_cfg` set to `key:value` pairs in `order`, joined by commas.
fn tb_cfg_configs(values: &[(&str, &[&str])], order: &[&str]) -> Vec<ConfigurationSpec> {
    let mut combinations: Vec<Vec<(&str, &str)>> = vec![Vec::new()];
    for &(key, choices) in values {
        combinations = combinations
            .into_iter()
            .flat_map(|combination| {
                choices.iter().map(move |&choice| {
                    let mut extended = combination.clone();
                    extended.push((key, choice));
                    extended
                })
            })
            .collect();
    }
    combinations
        .into_iter()
        .map(|combination| {
            let encoded = order
                .iter()
                .map(|key| {
                    let (_, value) = combination
                        .iter()
                        .find(|(name, _)| name == key)
                        .expect("every key has a value");
                    format!("{key}:{value}")
                })
                .collect::<Vec<_>>()
                .join(",");
            config_with(&encoded, &[("encoded_tb_cfg", &encoded)])
        })
        .collect()
}
